import SwiftUI
import WidgetSandbox

/// Loads every widget of the given corpus groups (generated by default, or
/// compat) on the real native stack and records the same facts the web suite
/// checks (minus the pixel diff, which needs a reference renderer): loaded, not
/// dead, no JS errors, plus the diagnostics. The result list is also written to
/// a JSON report (`DemoReport`: the simulator's app container on iOS,
/// Application Support on macOS).
struct GeneratedRunnerView: View {
    var groups = Corpus.generatedGroups
    var reportName = "generated-report.json"
    var autostart = false

    struct Row: Identifiable, Encodable {
        var id: String { group + "/" + file }
        let group: String
        let file: String
        let loaded: Bool
        let dead: String?
        let errors: [String]
        let diags: [String: Int]
        let jsMs: Double
        let tasks: Int
        let nodes: Int
        var pass: Bool { loaded && dead == nil && errors.isEmpty }
    }

    @State private var status = "Loads each widget, waits for `loaded` + 1 s, records errors and diagnostics."
    @State private var current: WidgetModel?
    @State private var rows: [Row] = []
    @State private var running = false

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text(status).font(.caption)
            HStack {
                Button(running ? "Running…" : "Run all") { Task { await run() } }.disabled(running)
                Spacer()
                // Per-group tallies for a couple of groups; one total for the 12 Telegram chats.
                if groups.count > 2 {
                    if !rows.isEmpty { Text("\(rows.filter(\.pass).count)/\(rows.count)").font(.caption.bold()).foregroundStyle(rows.allSatisfy(\.pass) ? .green : .red) }
                } else {
                    ForEach(groups, id: \.self) { g in
                        let rs = rows.filter { $0.group == g }
                        if !rs.isEmpty {
                            Text("\(g.split(separator: "/").last ?? ""): \(rs.filter(\.pass).count)/\(rs.count)")
                                .font(.caption.bold()).foregroundStyle(rs.allSatisfy(\.pass) ? .green : .red)
                        }
                    }
                }
            }
            if let current { WidgetView(host: current.host).id(ObjectIdentifier(current)).frame(width: 360, height: max(current.diagnostics.height, 24)).background(DemoColor.bubble) }
            List(rows) { r in
                VStack(alignment: .leading, spacing: 2) {
                    HStack {
                        Text(r.pass ? "✅" : "❌")
                        Text(r.file).font(.caption).lineLimit(1)
                        Spacer()
                        Text(String(format: "%.0f ms · %d nodes", r.jsMs, r.nodes)).font(.caption2).foregroundStyle(.secondary)
                    }
                    let extra = (r.dead.map { ["dead: \($0)"] } ?? []) + r.errors + r.diags.filter { $0.key != "boot" && $0.key != "library" }.map { "\($0.key)×\($0.value)" }
                    if !extra.isEmpty { Text(extra.joined(separator: " · ")).font(.caption2).foregroundStyle(r.pass ? .orange : .red).lineLimit(2) }
                }
            }
        }
        .padding()
        .navigationTitle(groups == ["compat"] ? "Compat corpus" : groups.first?.hasPrefix("htmlbubbles") == true ? "Telegram demos" : groups.first?.hasPrefix("common") == true ? "Common-profile corpus" : groups.first?.hasPrefix("showcase") == true ? "Showcase" : "Generated corpus")
        .task { if autostart { await run(); DemoAutorun.finished() } }
    }

    private func run() async {
        running = true
        rows = []
        for group in groups {
            for file in Corpus.files(in: group) {
                status = "loading \(group)/\(file)"
                guard let model = try? WidgetModel(html: Corpus.html(group: group, file: file), theme: WidgetTheme(), width: 360, options: DemoAutorun.hostOptions, rendererFactory: DemoRenderer.factory) else { continue }
                current = model
                let deadline = Date().addingTimeInterval(8)
                while Date() < deadline, !model.diagnostics.loaded, model.diagnostics.dead == nil {
                    try? await Task.sleep(nanoseconds: 100_000_000)
                }
                try? await Task.sleep(nanoseconds: 1_000_000_000)
                let d = model.diagnostics
                rows.append(Row(
                    group: group, file: file, loaded: d.loaded, dead: d.dead,
                    errors: d.logs.filter { $0.level == "error" }.map { String($0.text.split(separator: "\n").first ?? "").prefix(160) }.map(String.init),
                    diags: d.diags.mapValues(\.count), jsMs: d.stats.jsMs, tasks: d.stats.tasks, nodes: d.nodes))
                current = nil
            }
        }
        let passed = rows.filter(\.pass).count
        status = "done — \(passed)/\(rows.count) pass" + DemoReport.write(reportName, rows)
        running = false
    }
}
